schema.sql:
CREATE ROLE app LOGIN NOSUPERUSER NOINHERIT;
CREATE ROLE invoice_purge NOLOGIN NOSUPERUSER NOINHERIT;

CREATE TABLE accounts (
    id text PRIMARY KEY,
    is_demo boolean NOT NULL
);

CREATE TABLE orders (
    id text PRIMARY KEY,
    account_id text NOT NULL REFERENCES accounts(id),
    state text NOT NULL DEFAULT 'NEW'
);

CREATE TABLE invoice_audit (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT
);

CREATE FUNCTION reject_audit_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF current_user <> 'invoice_purge' THEN
        RAISE EXCEPTION 'invoice audit records are immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
END
$$;

CREATE TRIGGER invoice_audit_immutable
BEFORE DELETE ON invoice_audit
FOR EACH ROW EXECUTE FUNCTION reject_audit_delete();

CREATE FUNCTION reject_audit_truncate() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'invoice audit records cannot be truncated'
        USING ERRCODE = '55000';
END
$$;

CREATE TRIGGER invoice_audit_no_truncate
BEFORE TRUNCATE ON invoice_audit
FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_truncate();

CREATE FUNCTION complete_order(order_id text) RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    completed_order_id text;
BEGIN
    UPDATE orders AS o SET state = 'DONE'
    WHERE o.id = complete_order.order_id AND o.state <> 'DONE'
    RETURNING o.id INTO completed_order_id;

    IF completed_order_id IS NOT NULL THEN
        INSERT INTO invoice_audit(order_id) VALUES (completed_order_id);
    END IF;
END
$$;

-- Keep this list in sync with the catalog check below. These are the
-- restrictive FK references on tables whose rows the reset routine deletes.
CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    expected_references text[] := ARRAY['invoice_audit', 'orders'];
    actual_references text[];
    unsupported_references text[];
    target_account accounts%ROWTYPE;
BEGIN
    SELECT a.* INTO target_account
    FROM public.accounts AS a
    WHERE a.id = purge_demo_account.account_id
    FOR UPDATE;

    IF NOT FOUND OR NOT target_account.is_demo THEN
        RETURN;
    END IF;

    SELECT array_agg(DISTINCT c.conrelid::regclass::text ORDER BY c.conrelid::regclass::text)
    INTO actual_references
    FROM pg_catalog.pg_constraint AS c
    WHERE c.contype = 'f'
      AND c.confdeltype IN ('a', 'r')
      AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass,
                          'public.invoice_audit'::regclass);

    SELECT array_agg(x.reference_name ORDER BY x.reference_name)
    INTO unsupported_references
    FROM unnest(coalesce(actual_references, ARRAY[]::text[])) AS x(reference_name)
    WHERE x.reference_name <> ALL (expected_references);

    IF unsupported_references IS NOT NULL THEN
        RAISE EXCEPTION 'unsupported restrictive foreign-key references: %', unsupported_references
            USING ERRCODE = 'P0001';
    END IF;

    -- Delete children first. The audit trigger permits this only while
    -- current_user is this function's dedicated, non-login owner.
    DELETE FROM public.invoice_audit AS ia
    USING public.orders AS o
    WHERE ia.order_id = o.id AND o.account_id = target_account.id;

    DELETE FROM public.orders AS o WHERE o.account_id = target_account.id;
    DELETE FROM public.accounts AS a WHERE a.id = target_account.id;
END
$$;

ALTER FUNCTION purge_demo_account(text) OWNER TO invoice_purge;
GRANT SELECT, DELETE ON orders, invoice_audit TO invoice_purge;
GRANT SELECT, UPDATE, DELETE ON accounts TO invoice_purge;
GRANT USAGE, SELECT ON SEQUENCE invoice_audit_id_seq TO app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app;
GRANT EXECUTE ON FUNCTION complete_order(text) TO app;
GRANT EXECUTE ON FUNCTION purge_demo_account(text) TO app;

-- Fail schema validation when restrictive FKs referencing the reset tables
-- drift from the list used by purge_demo_account. Run this as part of schema
-- verification after migrations.
DO $$
DECLARE
    expected_references text[] := ARRAY['invoice_audit', 'orders'];
    actual_references text[];
BEGIN
    SELECT array_agg(DISTINCT c.conrelid::regclass::text ORDER BY c.conrelid::regclass::text)
    INTO actual_references
    FROM pg_catalog.pg_constraint AS c
    WHERE c.contype = 'f'
      AND c.confdeltype IN ('a', 'r')
      AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass,
                          'public.invoice_audit'::regclass);

    IF actual_references IS DISTINCT FROM expected_references THEN
        RAISE EXCEPTION 'purge_demo_account FK reference list mismatch: expected %, found %',
            expected_references, actual_references;
    END IF;
END
$$;
